// Словарь Sprut.Hub для скриптов имитации: перечисления `HS` и `HC` с
// метаданными. ФАЙЛ СОБРАН `node tools/hub-types.mjs` из
// `Sprut.Hub_Tools/ScenarioTemplate` (`spruthub.js` — имена, `sh_types.json` —
// метаданные); руками не править, а пересобрать. Формат характеристики —
// `Boolean | Integer | Long | Double | String` или `null`, если файл хаба её не
// описывает; `values` — допустимые значения `[{code, key}]`.

const HUB_TYPE_FREEZE = (value) => Object.freeze(value);

